package local.skyfamily;
import android.graphics.*;import android.net.Uri;import android.util.Xml;import org.xmlpull.v1.XmlPullParser;import java.net.*;import java.io.*;import java.util.*;
final class AudioMetadata {
 static class Info{String title="",artist="",album="",artUrl="";boolean taggedTitle=false;Bitmap artwork;int tint=0xff17222e;}
 static String clean(String text){if(text==null)return "";String value=text.replace('\u0000',' ').replace('\r',' ').replace('\n',' ').trim();return value.substring(0,Math.min(512,value.length()));}
 static Info basic(String address,String metadata,String fallback){Info info=new Info();String creator="";try{if(metadata!=null&&metadata.length()<=65536&&!metadata.toUpperCase(Locale.US).contains("<!DOCTYPE")){XmlPullParser parser=Xml.newPullParser();parser.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);parser.setInput(new StringReader(metadata));int events=0;for(int event=parser.getEventType();event!=XmlPullParser.END_DOCUMENT;event=parser.next()){if(++events>10000||parser.getDepth()>64)break;if(event!=XmlPullParser.START_TAG)continue;String key=parser.getName();if(key.equals("title")&&info.title.isEmpty()){info.title=clean(parser.nextText());info.taggedTitle=!info.title.isEmpty();}else if(key.equals("artist")&&info.artist.isEmpty())info.artist=clean(parser.nextText());else if(key.equals("creator")&&creator.isEmpty())creator=clean(parser.nextText());else if(key.equals("album")&&info.album.isEmpty())info.album=clean(parser.nextText());else if(key.equals("albumArtURI")&&info.artUrl.isEmpty())info.artUrl=parser.nextText().trim();}}}catch(Exception ignored){}if(info.artist.isEmpty())info.artist=creator;if(info.title.isEmpty()){String value=clean(fallback);if(value.isEmpty()||value.equals("Received media")||value.equals("legacydash")){try{value=clean(Uri.parse(address).getLastPathSegment());}catch(Exception ignored){value="";}}info.title=value.isEmpty()?"Unknown title":value;}info.artUrl=safeUrl(address,info.artUrl);return info;}
 static String safeUrl(String base,String value){if(value==null||value.trim().isEmpty()||value.length()>4096)return "";try{URI uri=new URI(base).resolve(value.trim().replace(" ","%20"));String scheme=uri.getScheme();if(!("http".equalsIgnoreCase(scheme)||"https".equalsIgnoreCase(scheme))||uri.getHost()==null||uri.getUserInfo()!=null)return "";return uri.toASCIIString();}catch(Exception error){return "";}}
 static class Task{volatile HttpURLConnection connection;volatile boolean cancelled=false;void cancel(){cancelled=true;HttpURLConnection current=connection;if(current!=null)current.disconnect();}void check()throws IOException{if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException();}
 HttpURLConnection open(String address,boolean range)throws Exception{String next=safeUrl(address,address);if(next.isEmpty())throw new IOException("HTTP(S) media required");for(int redirects=0;redirects<=3;redirects++){check();HttpURLConnection current=(HttpURLConnection)new URL(next).openConnection();connection=current;current.setInstanceFollowRedirects(false);current.setConnectTimeout(6000);current.setReadTimeout(6000);current.setRequestProperty("User-Agent","legacydash/0.25");if(range)current.setRequestProperty("Range","bytes=0-1048575");int status=current.getResponseCode();if(status==301||status==302||status==303||status==307||status==308){String target=safeUrl(next,current.getHeaderField("Location"));current.disconnect();if(target.isEmpty()||next.startsWith("https:")&&!target.startsWith("https:"))throw new IOException("Unsafe redirect");next=target;continue;}if(status!=200&&status!=206){current.disconnect();throw new IOException("HTTP "+status);}return current;}throw new IOException("Too many redirects");}
 byte[] read(InputStream input,int maximum)throws Exception{ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){check();if(output.size()+count>maximum)throw new IOException("Artwork too large");output.write(buffer,0,count);}return output.toByteArray();}
 Bitmap decode(byte[] data){try{BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth<1||options.outHeight<1||options.outWidth>12000||options.outHeight>12000||(long)options.outWidth*options.outHeight>40000000L)return null;options.inSampleSize=1;while(options.outWidth/options.inSampleSize>512||options.outHeight/options.inSampleSize>512)options.inSampleSize*=2;options.inJustDecodeBounds=false;return BitmapFactory.decodeByteArray(data,0,data.length,options);}catch(OutOfMemoryError error){return null;}}
 void exact(InputStream input,byte[] target)throws Exception{int position=0;while(position<target.length){check();int count=input.read(target,position,target.length-position);if(count<0)throw new EOFException();position+=count;}}
 Info load(String address,String metadata,String fallback){Info info=basic(address,metadata,fallback);try{if(!info.artUrl.isEmpty()){HttpURLConnection current=open(info.artUrl,false);try(InputStream input=current.getInputStream()){info.artwork=decode(read(input,5242880));}finally{current.disconnect();connection=null;}}}catch(Exception ignored){}if(!cancelled&&(!info.taggedTitle||info.artist.isEmpty()||info.album.isEmpty()||info.artwork==null))try{id3(address,info);}catch(Exception ignored){}if(info.artwork!=null){long red=0,green=0,blue=0;int count=0;for(int y=0;y<info.artwork.getHeight();y+=Math.max(1,info.artwork.getHeight()/8))for(int x=0;x<info.artwork.getWidth();x+=Math.max(1,info.artwork.getWidth()/8)){int color=info.artwork.getPixel(x,y);red+=Color.red(color);green+=Color.green(color);blue+=Color.blue(color);count++;}if(count>0)info.tint=Color.rgb(10+(int)(red/count)/5,10+(int)(green/count)/5,14+(int)(blue/count)/5);}return info;}
 int sync(byte[] data,int at){for(int i=0;i<4;i++)if((data[at+i]&128)!=0)return -1;return (data[at]&127)<<21|(data[at+1]&127)<<14|(data[at+2]&127)<<7|data[at+3]&127;}
 int integer(byte[] data,int at){long value=((long)(data[at]&255)<<24)|((long)(data[at+1]&255)<<16)|((long)(data[at+2]&255)<<8)|(data[at+3]&255);return value>Integer.MAX_VALUE?-1:(int)value;}
 byte[] unsync(byte[] data){ByteArrayOutputStream output=new ByteArrayOutputStream();for(int i=0;i<data.length;i++){output.write(data[i]);if((data[i]&255)==255&&i+1<data.length&&data[i+1]==0)i++;}return output.toByteArray();}
 String text(byte[] data){if(data.length<2)return "";String[] encodings={"ISO-8859-1","UTF-16","UTF-16BE","UTF-8"};int encoding=data[0]&255;if(encoding>3)return "";try{return clean(new String(data,1,data.length-1,encodings[encoding]));}catch(Exception error){return "";}}
 void picture(byte[] data,Info info){if(data.length<5||info.artwork!=null)return;int encoding=data[0]&255,at=1;while(at<data.length&&data[at]!=0)at++;if(++at>=data.length)return;at++;if(encoding==1||encoding==2){while(at+1<data.length&&(data[at]!=0||data[at+1]!=0))at+=2;at+=2;}else{while(at<data.length&&data[at]!=0)at++;at++;}if(at>=data.length)return;info.artwork=decode(Arrays.copyOfRange(data,at,data.length));}
 void id3(String address,Info info)throws Exception{HttpURLConnection current=open(address,true);try(InputStream input=current.getInputStream()){byte[] header=new byte[10];exact(input,header);if(header[0]!='I'||header[1]!='D'||header[2]!='3')return;int version=header[3]&255,size=sync(header,6),flags=header[5]&255;if((version!=3&&version!=4)||size<1||size>1048566)return;byte[] tag=new byte[size];exact(input,tag);if(version==3&&(flags&128)!=0)tag=unsync(tag);int at=0;if((flags&64)!=0){if(tag.length<4)return;int extended=version==4?sync(tag,0):integer(tag,0)+4;if(extended<4||extended>tag.length)return;at=extended;}for(int frames=0;frames<256&&at+10<=tag.length;frames++){check();String name=new String(tag,at,4,"US-ASCII");if(!name.matches("[A-Z0-9]{4}"))break;int length=version==4?sync(tag,at+4):integer(tag,at+4),frameFlags=tag[at+9]&255;at+=10;if(length<=0||length>tag.length-at)break;byte[] data=Arrays.copyOfRange(tag,at,at+length);at+=length;if(version==3&&(frameFlags&224)!=0||version==4&&(frameFlags&77)!=0)continue;if(version==4&&((flags&128)!=0||(frameFlags&2)!=0))data=unsync(data);if(name.equals("TIT2")&&!info.taggedTitle){String title=text(data);if(!title.isEmpty()){info.title=title;info.taggedTitle=true;}}else if(name.equals("TPE1")&&info.artist.isEmpty())info.artist=text(data);else if(name.equals("TALB")&&info.album.isEmpty())info.album=text(data);else if(name.equals("APIC"))picture(data,info);}}finally{current.disconnect();connection=null;}}
 }
}
